use std::future::Future;
use std::pin::{Pin, pin};
use std::sync::Arc;
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, Thread};

struct Countdown {
    remaining: u32,
}

impl Future for Countdown {
    type Output = &'static str;

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        if self.remaining == 0 {
            Poll::Ready("liftoff")
        } else {
            println!("{}...", self.remaining);
            self.remaining -= 1;
            cx.waker().wake_by_ref(); // poll me again
            Poll::Pending
        }
    }
}

fn main() {
    println!("{}", block_on(Countdown { remaining: 3 }));
}

struct ThreadWaker(Thread);
impl Wake for ThreadWaker {
    fn wake(self: Arc<Self>) {
        self.0.unpark();
    }
}
fn block_on<F: Future>(fut: F) -> F::Output {
    let mut fut = pin!(fut);
    let waker = Waker::from(Arc::new(ThreadWaker(thread::current())));
    let mut cx = Context::from_waker(&waker);
    loop {
        match fut.as_mut().poll(&mut cx) {
            Poll::Ready(v) => return v,
            Poll::Pending => thread::park(),
        }
    }
}

blocks.md:
A future produces **one** value. A **stream** produces a **sequence** of values over time: messages from a channel, lines from a socket, ticks of a timer. It is the async version of `Iterator`:

```rust
trait Stream {
    type Item;
    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>>;
}
```

`Iterator::next` returns `Option<Item>`; `poll_next` returns that **inside** a `Poll`: maybe not yet (`Pending`), the next item (`Ready(Some(item))`), or finished (`Ready(None)`). The standard library does not have `Stream` yet; the `futures` crate and Tokio's `tokio-stream` define it, along with a `StreamExt` trait that adds `next().await`, `map`, `filter`, `throttle`, `timeout` and friends:

```rust
let mut stream = trpl::stream_from_iter(values.iter().map(|n| n * 2));
while let Some(value) = stream.next().await {
    println!("The value was: {value}");
}
```

Recent Rust lets traits contain `async fn` directly:

```rust
trait Fetcher {
    async fn fetch(&self, url: &str) -> Result<String, Error>;
}
```

and supports **async closures**, `async |x| { ... }`, whose calls return futures, with matching traits `AsyncFn`, `AsyncFnMut` and `AsyncFnOnce`. One limitation of `async fn` in traits: such traits cannot yet be used as `dyn Trait` trait objects, and callers cannot require the returned future to be `Send`. The `async-trait` crate and the newer `trait-variant` crate cover those cases.

